'use client';

import { useRef, useState, useTransition, type ChangeEvent } from 'react';
import { useRouter } from 'next/navigation';
import { useTranslations } from 'next-intl';
import { importMenuCsvAction } from '@/app/actions/menu-import.actions';

type ImportStatus =
  | { kind: 'success'; message: string }
  | { kind: 'error'; message: string }
  | null;

/** Uploads the filled CSV menu sheet generated by DownloadTemplateButton. */
export function UploadTemplateButton(): React.JSX.Element {
  const t = useTranslations('owner.menu');
  const router = useRouter();
  const inputRef = useRef<HTMLInputElement>(null);
  const [pending, start] = useTransition();
  const [status, setStatus] = useState<ImportStatus>(null);

  function pickFile(): void {
    inputRef.current?.click();
  }

  function onFileChange(event: ChangeEvent<HTMLInputElement>): void {
    const file = event.target.files?.[0];
    event.target.value = '';
    if (!file) return;

    const formData = new FormData();
    formData.set('file', file);
    setStatus(null);
    start(async () => {
      const res = await importMenuCsvAction(formData);
      if (res.ok) {
        setStatus({
          kind: 'success',
          message: t('importSuccess', { items: res.value.itemsCreated }),
        });
        router.refresh();
      } else {
        setStatus({ kind: 'error', message: res.message });
      }
    });
  }

  return (
    <div className="flex max-w-full flex-col items-end gap-2">
      <input ref={inputRef} type="file" accept=".csv,text/csv" hidden onChange={onFileChange} />
      <button
        type="button"
        onClick={pickFile}
        disabled={pending}
        className="inline-flex h-9 items-center gap-2 rounded-full border border-border-default bg-surface-base px-4 text-sm font-semibold text-text-primary transition hover:bg-surface-raised disabled:cursor-not-allowed disabled:opacity-50"
      >
        {pending ? (
          <span
            aria-hidden
            className="inline-block size-4 animate-spin rounded-full border-2 border-current border-t-transparent"
          />
        ) : (
          <svg width="15" height="15" viewBox="0 0 16 16" fill="none" aria-hidden>
            <path d="M8 14V6m0 0L5 9m3-3 3 3M3 3h10" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        )}
        {pending ? t('importing') : t('uploadTemplate')}
      </button>
      {status ? (
        <p
          className={`max-w-[280px] text-right text-xs ${
            status.kind === 'success' ? 'text-success' : 'text-danger'
          }`}
        >
          {status.message}
        </p>
      ) : null}
    </div>
  );
}
